INSERT INTO `lesson` (`ID`, `CONTENT`, `sort_order`, `TITLE`, `section_id`) VALUES
(1, '<p>In deze cursus gaan we aan de slag met <span class=\"woordtip\" data-tip=\"Interactiviteit betekent dat een computer, spel of apparaat meteen reageert op wat jij doet, kiest of klikt, zodat jij de leiding hebt over wat er gebeurt.\">interactiviteit</span>. Je gaat starten met het maken van een quiz in Google Docs. Zo\'n quiz lijkt wel een soort website. Je kunt er op klikken en als je op het juiste antwoord klikt kun je door naar de volgende vraag. Hieronder een voorbeeld een quiz gemaakt door een leerling. Probeer de quiz maar te spelen.</p>\r\n<p><a href=\"https://docs.google.com/presentation/d/1r4j2O4_RSSl3c9dkeDZA6AVG-LcqVTK9nDJD1lOlc-o/present?token=AC4w5VhP3wmFlgLJuZUbkqPxH6d8TMC-1A%3A1600328701412&amp;includes_info_params=1&amp;eisi=CPvLlv7Y7-sCFdCrygodv_wKhQ#slide=id.g609ae32ee5_0_116\" target=\"_blank\" rel=\"noopener noreferrer\">voorbeeldquiz</a></p>\r\n<h3>Een tooltip</h3>\r\n<p>Een tooltip is uitleg over een bepaalde term zoals <span class=\"woordtip\" data-tip=\"Dit is een tooltip. Je komt ze af en toe tegen.\">deze </span>(ga er met je muis overheen).</p>\r\n<h2>Werken in the cloud</h2>\r\n<p>Op een computer kun je op twee manieren werken:</p>\r\n<ul>\r\n<li>Met een applicatie zoals bijvoorbeeld Microsoft Word;</li>\r\n<li>In de cloud, ook wel <span class=\"nadruk\">cloud computing</span> genoemd.</li>\r\n</ul>\r\n<p>De laatste jaren is er meer en meer een trend naar werken in de cloud. Bij de eerste optie moet er altijd een programma zijn ge&iuml;nstalleerd op je computer. Bij de laatste optie, dus Cloud Computing, &nbsp;is dat niet het geval.&nbsp;<br><br>Binnen deze lessenreeks gaan wij werken in de cloud met Google Presentations en hierbinnen een interactieve quiz in maken. Door het maken van deze quiz raak je goed thuis in Google Docs. Later kun je altijd weer overstappen op bijvoorbeeld <span class=\"woordtip\" data-tip=\"Microsoft Office is een verzameling handige computerprogramma\'s waarmee je makkelijk teksten kunt typen, presentaties kunt maken en overzichtelijke lijsten of berekeningen kunt bijhouden.\">Microsoft Office.&nbsp;</span></p>', 0, 'Een interactieve quiz', 1),
(2, '<p>Je gaat een nieuwe presentatie aanmaken. Hiervoor ga je eerst naar <a href=\"https://classroom.google.com\" target=\"_blank\" rel=\"noopener\">Google Classroom</a> en log je in met je edictum account (hier heb je als het goed is al uitleg over gekregen). Klik binnen Google Classroom op de juiste klas (Informatica) en daarna op <span style=\"background-color: #fbeeb8;\">Schoolwerk</span>.</p>\r\n<p><img src=\"lesson-images/2\" alt=\"\" width=\"510\" height=\"77\"></p>\r\n<p>Hier klik je op de opdracht Quiz en klik je op<span style=\"background-color: #fbeeb8;\"> instructies bekijken</span>.</p>\r\n<p><img src=\"lesson-images/4\" alt=\"\" width=\"502\" height=\"456\"></p>\r\n<p>Nu gaan we de quiz daadwerkelijk maken. Klik op <span style=\"background-color: #fbeeb8;\">Toevoegen of maken</span> en kies daarna op<span style=\"background-color: #fbeeb8;\"> Presentaties</span>.</p>\r\n<p><img src=\"lesson-images/5\" alt=\"\" width=\"399\" height=\"664\"></p>\r\n<p>Hierna heb je de basis gelegd om een quiz te maken. Overigens heet deze leerling \"Nieuwe Les\".</p>\r\n<p><img src=\"lesson-images/6\" alt=\"\" width=\"429\" height=\"329\"></p>\r\n<p>Nu kan je op je presentatie klikken en kom je in een nieuw scherm met je lege presentatie.</p>\r\n<p>Je kunt voor een presentatie <span class=\"woordtip\" data-tip=\"Hiermee stel je een thema in.\">een automatische opmaak</span> kiezen. Binnen deze cursus mag je echter alleen het thema&nbsp;<strong>Eenvoudig Licht</strong> gebruiken. <br>Andere thema\'s mag je niet gebruiken. We willen je namelijk leren om zelf een opmaak in te stellen.</p>\r\n<p>Vervolgens heb je de nieuwe presentatie aangemaakt. Verander nu eerst de naam van de presentatie in Quiz over ...... <br>In dit voorbeeld&nbsp;gaat de quiz over computers. <br>Kies voor jouw quiz een eigen onderwerp zoals bijvoorbeeld:</p>\r\n<ul>\r\n<li>je hobby</li>\r\n<li>je school</li>\r\n<li>je vereniging</li>\r\n<li>etc.</li>\r\n</ul>\r\n<p>Nog iets over werken in de cloud. Iedere 5 seconden wordt je werk opgeslagen. Dat hoef je niet zelf te doen. Als de bel gaat of de docent zegt af te sluiten dan kun je eenvoudig zonder iets kwijt te raken de computer afsluiten.</p>', 10, 'Een nieuwe presentatie maken', 1);

